sql.where:

    AND a.member_id = #{queryParams.memberId}




            AND FIND_IN_SET(a.status, #{queryParams.status})


            AND a.status = #{queryParams.status}




    AND a.after_sale_type = #{queryParams.afterSaleType}


    AND (a.after_sale_no LIKE CONCAT('%', #{queryParams.keywords}, '%')
    OR a.order_no LIKE CONCAT('%', #{queryParams.keywords}, '%')
    OR EXISTS (
        SELECT 1 FROM oms_order_after_sale_item ai
        WHERE ai.after_sale_id = a.id
          AND ai.sku_name LIKE CONCAT('%', #{queryParams.keywords}, '%')
    ))


    AND a.create_time >= #{queryParams.beginDate}


    AND a.create_time < DATE_ADD(#{queryParams.endDate}, INTERVAL 1 DAY)


    AND a.supplier_id = #{queryParams.supplierId}

AND a.deleted = 0

mapper.select:
SELECT a.after_sale_no AS afterSaleNo, a.order_no AS orderNo, a.member_id AS memberId, a.status, CASE a.status WHEN 1 THEN '待审核' WHEN 2 THEN '已拒绝' WHEN 3 THEN '待退货' WHEN 4 THEN '退货中' WHEN 5 THEN '待收货' WHEN 6 THEN '退款中' WHEN 7 THEN '退款成功' WHEN 8 THEN '退款失败' WHEN 9 THEN '已取消' ELSE '未知状态' END AS statusLabel, a.refund_amount AS refundAmount, a.reason, a.description, a.carrier_name AS carrierName, a.tracking_no AS trackingNo, a.create_time AS createTime, a.handle_time AS handleTime, a.handle_note AS handleNote, a.refund_time AS refundTime FROM oms_order_after_sale a
AND a.member_id = #{memberId}
AND FIND_IN_SET(a.status, #{status})
AND a.status = #{status}
AND (a.after_sale_no LIKE CONCAT('%', #{afterSaleNo}, '%')
AND a.order_no LIKE CONCAT('%', #{orderNo}, '%'))
AND a.create_time >= #{beginDate}
AND a.create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND a.supplier_id = #{supplierId}
ORDER BY a.create_time DESC
